begin;
create table public.arena_alliances(id uuid primary key default gen_random_uuid(),founder_id uuid not null references public.profiles(id) on delete restrict,name text not null check(length(trim(name)) between 3 and 40),tag text not null unique check(tag~'^[A-Z0-9]{2,5}$'),description text not null default'' check(length(description)<=240),emblem text not null default'✦',visibility text not null default'open' check(visibility in('open','approval','invite')),min_trophies integer not null default 0 check(min_trophies>=0),level integer not null default 1 check(level between 1 and 100),xp integer not null default 0 check(xp>=0),weekly_glory integer not null default 0 check(weekly_glory>=0),max_members integer not null default 40 check(max_members between 5 and 50),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.arena_alliance_members(alliance_id uuid not null references public.arena_alliances(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role text not null default'member' check(role in('founder','elder','guardian','member')),contribution integer not null default 0 check(contribution>=0),joined_at timestamptz not null default now(),primary key(alliance_id,user_id),unique(user_id));
create table public.arena_alliance_activities(id bigint generated always as identity primary key,alliance_id uuid not null references public.arena_alliances(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,kind text not null check(kind in('created','join','promotion','mission','battle','system')),message text not null check(length(message) between 1 and 240),created_at timestamptz not null default now());
create table public.arena_alliance_missions(id uuid primary key default gen_random_uuid(),alliance_id uuid not null references public.arena_alliances(id) on delete cascade,title text not null,description text not null,target integer not null check(target>0),progress integer not null default 0 check(progress>=0),reward_label text not null,starts_at timestamptz not null default date_trunc('week',now()),ends_at timestamptz not null default date_trunc('week',now())+interval'7 days');
create trigger arena_alliances_set_updated_at before update on public.arena_alliances for each row execute function public.set_updated_at();
create index arena_alliance_members_alliance_idx on public.arena_alliance_members(alliance_id,contribution desc);create index arena_alliance_activity_idx on public.arena_alliance_activities(alliance_id,created_at desc);
alter table public.arena_alliances enable row level security;alter table public.arena_alliances force row level security;alter table public.arena_alliance_members enable row level security;alter table public.arena_alliance_members force row level security;alter table public.arena_alliance_activities enable row level security;alter table public.arena_alliance_activities force row level security;alter table public.arena_alliance_missions enable row level security;alter table public.arena_alliance_missions force row level security;
revoke all on public.arena_alliances,public.arena_alliance_members,public.arena_alliance_activities,public.arena_alliance_missions from anon,authenticated;
create or replace function public.arena_create_alliance(p_name text,p_tag text,p_description text default'',p_visibility text default'open') returns uuid language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_id uuid;begin if v_user is null then raise exception'authentication required';end if;if exists(select 1 from public.arena_alliance_members where user_id=v_user)then raise exception'already in alliance';end if;if length(trim(p_name))not between 3 and 40 or upper(trim(p_tag))!~'^[A-Z0-9]{2,5}$'or p_visibility not in('open','approval','invite')then raise exception'invalid alliance';end if;insert into public.arena_alliances(founder_id,name,tag,description,visibility)values(v_user,trim(p_name),upper(trim(p_tag)),trim(p_description),p_visibility)returning id into v_id;insert into public.arena_alliance_members values(v_id,v_user,'founder',0,now());insert into public.arena_alliance_activities(alliance_id,actor_id,kind,message)values(v_id,v_user,'created','A Aliança foi fundada e sua história começou.');insert into public.arena_alliance_missions(alliance_id,title,description,target,reward_label)values(v_id,'Jornada de Fé','Vença batalhas em conjunto',50,'Baú da Aliança'),(v_id,'Sabedoria Compartilhada','Complete estudos e desafios',30,'500 Glória'),(v_id,'Servir uns aos outros','Ajude membros da Aliança',20,'Emblema semanal');return v_id;end;$$;
create or replace function public.arena_join_alliance(p_alliance_id uuid) returns void language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance public.arena_alliances%rowtype;begin if v_user is null then raise exception'authentication required';end if;if exists(select 1 from public.arena_alliance_members where user_id=v_user)then raise exception'already in alliance';end if;select * into v_alliance from public.arena_alliances where id=p_alliance_id and visibility='open' for update;if not found then raise exception'alliance unavailable';end if;if(select count(*) from public.arena_alliance_members where alliance_id=p_alliance_id)>=v_alliance.max_members then raise exception'alliance full';end if;insert into public.arena_alliance_members(alliance_id,user_id)values(p_alliance_id,v_user);insert into public.arena_alliance_activities(alliance_id,actor_id,kind,message)values(p_alliance_id,v_user,'join','Um novo guardião entrou na Aliança.');end;$$;
create or replace function public.arena_browse_alliances(p_query text default'',p_limit integer default 12) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(row_data order by weekly_glory desc,member_count desc),'[]'::jsonb)from(select a.id,a.name,a.tag,a.description,a.emblem,a.visibility,a.level,a.xp,a.weekly_glory,a.max_members,count(m.user_id)::integer member_count from public.arena_alliances a left join public.arena_alliance_members m on m.alliance_id=a.id where a.visibility='open'and(trim(p_query)=''or a.name ilike'%'||trim(p_query)||'%'or a.tag ilike'%'||trim(p_query)||'%')group by a.id order by a.weekly_glory desc,count(m.user_id)desc limit least(greatest(p_limit,1),30))row_data$$;
create or replace function public.arena_get_alliance_hub() returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_id uuid;v_result jsonb;begin if v_user is null then raise exception'authentication required';end if;select alliance_id into v_id from public.arena_alliance_members where user_id=v_user;if v_id is null then return null;end if;select jsonb_build_object('alliance',(select to_jsonb(x)from(select a.*,count(allm.user_id)::integer member_count,m.role,m.contribution from public.arena_alliances a join public.arena_alliance_members m on m.alliance_id=a.id and m.user_id=v_user left join public.arena_alliance_members allm on allm.alliance_id=a.id where a.id=v_id group by a.id,m.role,m.contribution)x),'members',(select coalesce(jsonb_agg(to_jsonb(x)order by contribution desc,joined_at),'[]'::jsonb)from(select user_id,role,contribution,joined_at from public.arena_alliance_members where alliance_id=v_id limit 50)x),'activities',(select coalesce(jsonb_agg(to_jsonb(x)order by created_at desc),'[]'::jsonb)from(select id,kind,message,created_at from public.arena_alliance_activities where alliance_id=v_id order by created_at desc limit 30)x),'missions',(select coalesce(jsonb_agg(to_jsonb(x)order by ends_at),'[]'::jsonb)from(select id,title,description,target,progress,reward_label,ends_at from public.arena_alliance_missions where alliance_id=v_id and ends_at>now())x))into v_result;return v_result;end;$$;
revoke all on function public.arena_create_alliance(text,text,text,text),public.arena_join_alliance(uuid),public.arena_browse_alliances(text,integer),public.arena_get_alliance_hub()from public;grant execute on function public.arena_create_alliance(text,text,text,text),public.arena_join_alliance(uuid),public.arena_browse_alliances(text,integer),public.arena_get_alliance_hub()to authenticated;
commit;
